var result = await HttpContext.AuthenticateAsync();
if (result.Succeeded && result.Principal.Identity is ClaimsIdentity identity)
{
    var authMethod = identity.FindFirst("idp")?.Value;
    var issuer = identity.FindFirst("iss")?.Value;

    if (!string.IsNullOrEmpty(authMethod))
    {
        _logger.LogInformation("User authenticated via {AuthMethod} ({Issuer})", 
            authMethod, issuer);
    }
}
